
// AI-assisted frontend prototype. The team must review and understand this code.
// No model runs here. Scenario fixtures demonstrate proposed uncertainty handling.
(() => {
'use strict';
const root=document.getElementById('main'), announce=document.getElementById('announce');
const key='fixforward-i3-site-v2';
const items=[{id:'fan',name:'Fan',icon:'🌀',family:'Heating & cooling'},{id:'toaster',name:'Toaster',icon:'🍞',family:'Everyday cooking'},{id:'kettle',name:'Kettle',icon:'🫖',family:'Everyday cooking'},{id:'headphones',name:'Headphones',icon:'🎧'},{id:'phone',name:'Phone',icon:'📱'},{id:'toy',name:'Electronic toy',icon:'🤖'},{id:'charger',name:'Charger',icon:'🔌'},{id:'bulb',name:'Light bulb',icon:'💡'}];
items.push({id:'blender',name:'Blender',icon:'🥤',family:'Blending & mixing'},{id:'mixer',name:'Mixer',icon:'🥣',family:'Blending & mixing'},{id:'processor',name:'Food processor',icon:'🥕',family:'Blending & mixing'},{id:'coffee',name:'Coffee machine',icon:'☕',family:'Coffee & quick meals'},{id:'airfryer',name:'Air fryer',icon:'🍟',family:'Coffee & quick meals'},{id:'microwave',name:'Microwave',icon:'🍲',family:'Coffee & quick meals'},{id:'vacuum',name:'Vacuum cleaner',icon:'🧹',family:'Cleaning'},{id:'steam',name:'Steam cleaner',icon:'🧼',family:'Cleaning'},{id:'dryer',name:'Hair dryer',icon:'💨',family:'Personal care'},{id:'shaver',name:'Shaver',icon:'🪒',family:'Personal care'},{id:'heater',name:'Heater',icon:'🌡️',family:'Heating & cooling'});
const learningIds=['fan','toaster','kettle','headphones','phone','toy','charger','bulb'];
const families=['Everyday cooking','Blending & mixing','Coffee & quick meals','Cleaning','Personal care','Heating & cooling'];
let saved={};try{const parsed=JSON.parse(localStorage.getItem(key)||'{}');if(parsed&&typeof parsed==='object')saved=parsed;}catch{}
let state={view:'home',item:'fan',mode:'child',stage:0,photo:'',scenario:'fan',busy:false,token:0,clues:[false,false],choice:null,correct:false,feedback:'',fromChild:false,answers:{},sound:saved.sound===true,stamps:Array.isArray(saved.stamps)?[...new Set(saved.stamps.filter(id=>learningIds.includes(id)))]:[],plan:saved.plan||null,model:'',quote:'',replacement:'',suburb:'',teacher:false,family:'Heating & cooling',resume:saved.resume||null,readActive:false};
const item=()=>items.find(i=>i.id===state.item)||items[0];
const itemNoun=()=>item().id==='headphones'?'pair of headphones':item().name.toLowerCase();
const article=()=>/^[aeiou]/.test(itemNoun())?'an':'a';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const persist=()=>{try{localStorage.setItem(key,JSON.stringify({sound:state.sound,stamps:state.stamps,plan:state.plan,resume:state.resume}));return true}catch{say('This browser cannot save progress. Keep this page open.');return false}};
function say(msg){announce.textContent='';setTimeout(()=>announce.textContent=msg,20)}
function go(view,push=true){
  if(!views[view])view='home';
  state.token++;state.busy=false;state.view=view;state.feedback='';
  if('speechSynthesis'in window)speechSynthesis.cancel();state.readActive=false;
  if(push&&window.history)window.history.pushState({view},'',`#/${view}`);
  render();root.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
}
function button(text,action,cls='primary'){return `<button type="button" class="${cls}" data-action="${action}">${text}</button>`}
function steps(n){return `<div class="steps" aria-label="Mission stages">${['Look','Choose','Discover'].map((label,i)=>i===n?`<strong aria-current="step">${i+1}. ${label}</strong>`:i<n?`<button data-stage="${i}">${i+1}. ${label}</button>`:`<span>${i+1}. ${label}</span>`).join('')}</div>`}
function itemGrid(mode='child'){
  const shown=items.filter(i=>mode==='child'?learningIds.includes(i.id):i.family===state.family);
  return `<div class="item-grid">${shown.map(i=>`<button class="item ${state.item===i.id?'selected':''}" data-item="${i.id}" aria-pressed="${state.item===i.id}">${state.item===i.id?'<span class="selected-tick" aria-hidden="true">✓</span>':''}<span class="icon" aria-hidden="true">${i.icon}</span><span class="item-name">${i.name}</span><small>${mode==='adult'?'Select this item':['fan','toaster','kettle'].includes(i.id)?'Another useful life':['bulb','charger'].includes(i.id)?'Find the right place':'Solve the mystery'}</small></button>`).join('')}</div>`;
}
function discoveryCount(){
 const ids=['phone','laptop','headphones','television','toy','remote_car','kettle','toaster','fan','vacuum','dryer','toothbrush','bulb','lamp','charger','powerbank','fridge','washer','drill','mower'];
 const seen=new Set(state.stamps);try{const records=JSON.parse(localStorage.getItem('fixforward-discovery-v1')||'{}')?.records||{};for(const id of ids)if(records[id]&&['spot','plan','service','episode'].some(k=>records[id][k]===true))seen.add(id);}catch{}return seen.size;
}
function settings(){
  const snd=document.getElementById('sound');snd.textContent=state.sound?'Sound on':'Sound off';snd.setAttribute('aria-pressed',String(state.sound));
  document.getElementById('book-count').textContent=String(discoveryCount());
  document.getElementById('read').textContent=state.readActive?'Stop reading':'Read this screen';
  const group=['adult','safety','next','services','general'].includes(state.view)?'adult':['choose','photo','identify','confirm','mission','recap','handoff'].includes(state.view)?'choose':['schools','teacherGuide'].includes(state.view)?'schools':state.view;
  document.querySelectorAll('.nav [data-go]').forEach(b=>{if(b.dataset.go===group)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
}
function scenarioStory(){
  if(['fan','toaster','kettle'].includes(state.item)){
    const fan=state.item==='fan',name=fan?'Flo':state.item==='toaster'?'Pip':'Kiki';
    return {title:`${name}’s next home`,intro:`${name} is ${article()} ${itemNoun()}. Her family no longer needs her. Bea would like one for her home.`,a:`In this made-up story, a qualified repairer checked ${name}. Her adult owner completed the sharing checks.`,b:`Bea wants ${name} and has agreed to give her a new home.`,question:'What could the adult owner do next?',options:['Arrange a new home with Bea','Put the item in a household bin','Ask a child to open the item'],answer:0,why:'Both clues matter: the sharing checks are complete and someone wants the working item.',lesson:'A working item may have another useful life.',check:'New clue: Bea no longer needs it. What changes?',checks:['The adult needs to find another suitable next step','The adult should send it to Bea anyway'],checkAnswer:0};
  }
  if(['bulb','charger'].includes(state.item))return {title:'The right place mystery',intro:`An adult has an old ${itemNoun()} to take to a collection service. Two places are nearby. Which clue would help?`,a:'The nearest place lists some electrical items, but does not say whether it accepts this one.',b:'A different service has confirmed that it accepts this exact type of item.',question:'Which clue helps the adult decide?',options:['Choose the closest place without checking','Use the service that confirmed item acceptance','Put it in a household recycling bin'],answer:1,why:'Different services accept different items. The adult needs confirmed acceptance before visiting.',lesson:'Check the item, then check the collection service.',check:'New clue: the service has changed its rules. What now?',checks:['Check acceptance again before visiting','Assume the old information is still correct'],checkAnswer:0};
  return {title:`The ${item().name.toLowerCase()} mystery`,intro:`An adult has an old ${itemNoun()}. A picture shows what it looks like, but something is missing.`,a:'A picture can suggest the item type. It cannot tell us whether this real item is safe or repairable.',b:'We do not know its condition or which service accepts it. An adult needs more information.',question:'What is the best first step?',options:['Put it in a household recycling bin','Open it and look inside','Ask an adult to find the missing information'],answer:2,why:'We need more information before deciding. A grown-up can find the right guidance.',lesson:'A picture does not tell the whole story.',check:'New clue: a clearer photo arrives. What is still missing?',checks:['Whether the real item is safe or repairable','All the information has now been checked'],checkAnswer:0};
}
function home(){return `<div class="home-top"><div><p class="eyebrow">Welcome to FixForward</p><h1>What would you like to do?</h1><p class="lead">A useful next step for your item. A new discovery for your child.</p></div><span class="soft-label">One place. Different journeys.</span></div><div class="home-paths"><section class="path-card adult-path"><p class="eyebrow">For households</p><h2>Let’s find its<br>next step.</h2><p>Get help with an appliance and make a plan you can act on.</p><div class="path-items" aria-hidden="true"><span class="path-item">🫖</span><span class="path-item">🌀</span><span class="path-item">🍞</span></div><button class="path-start" data-action="adult-entry">Help with an item</button></section><section class="path-card kid-path"><img class="entry-art" src="assets/kids-entry.webp" alt="A friendly fictional fan, toaster and headphones"><p class="eyebrow">Quest · Ages 7–12</p><h2>Small clues.<br>Big discoveries.</h2><p>Explore 20 items. Open clues, make a choice and discover why.</p><a class="path-start" href="discover/">Explore the Sorting Station</a></section></div><div class="home-note"><span>Planning a class activity? Start with a picture-based lesson.</span><button class="quiet" data-go="schools">Explore school mode</button></div><section class="lab-invite"><div><p class="eyebrow">New · My discovery home</p><h2>Open the door to a little wonder.</h2><p>Make an explorer. Walk through your 3D home. Visit any of the 21 electrical items, meet its parts and discover its story.</p></div><a class="primary" href="home/">Explore my 3D home</a></section><div class="home-support"><span><span class="tiny-icon" aria-hidden="true">◉</span> Photos are optional</span><span><span class="tiny-icon" aria-hidden="true">✓</span> Progress stays on this browser</span><span><span class="tiny-icon" aria-hidden="true">◌</span> Children learn. Adults decide.</span></div>${state.plan?`<div class="notice">Your saved plan: ${esc(state.plan.item)}. ${button('Open saved plan','saved-plan','quiet')}</div>`:''}`}
function choose(){return `<div class="topline"><button class="quiet" data-go="home">Back to home</button><span class="chip">Quest for kids</span></div><div class="quest-head"><div><p class="eyebrow">Choose your adventure</p><h1>Every item has a story.</h1><p class="lead">Pick an item and discover which clue changes its next chapter.</p></div><div class="book-mini"><strong>${state.stamps.length} / ${learningIds.length}</strong> discoveries in your book</div></div>${state.resume?`<div class="notice">You have a mission in progress. ${button('Continue my mission','resume-mission','quiet')}</div>`:''}<section class="discovery-invite"><div><strong>There’s more to discover.</strong><p>20 items, three sorting games and short discovery episodes.</p></div><a href="discover/">Explore the new activities</a></section>${itemGrid()}<div class="selection-bar"><div><strong>${item().name}</strong><p class="small muted">A short, made-up picture story</p></div><div class="action-row">${button('Explore this item','confirm-item','gold')}${button('Try a photo','photo-open','quiet')}</div></div><p class="section-note">Real items stay with grown-ups. Never open, switch on or collect a damaged item for this game.</p>`}
function photo(){return `<div class="topline"><button class="quiet" data-action="manual-select">Back to item choices</button><span class="chip">Photo helper</span></div><p class="eyebrow">Start with a picture</p><h1>What’s in your photo?</h1><p class="lead">Preview one item, then confirm what it is. You can always choose it yourself.</p><div class="twocol"><section class="panel"><h2>Your photo</h2><label for="upload">Choose or replace a photo</label><input id="upload" type="file" accept="image/jpeg,image/png,image/webp"><p class="small muted">JPG, PNG or WEBP · Up to 10 MB · No upload</p>${state.photo?`<img class="photo" src="${state.photo}" alt="Preview of your selected photo">${button('Remove photo','remove-photo','quiet')}`:'<div class="empty-photo"><div><strong aria-hidden="true">▧</strong><p>Your photo will appear here.</p><span class="small">You can also explore a sample response.</span></div></div>'}</section><section class="panel tint"><p class="eyebrow">Prototype controls</p><h2>Explore a sample response</h2><p>These responses are simulated. They do not recognise your uploaded image.</p><label for="scenario">Sample scenario</label><select id="scenario">${[['fan','Clear fan · suggested match'],['unknown','Light bulb · uncertain result'],['multiple','Several items · choose one'],['damaged','Damaged or hidden · uncertain'],['unsupported','Outside the model’s scope'],['error','Processing error · try again']].map(([v,l])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${l}</option>`).join('')}</select>${state.busy?'<div class="photo-loader"><span></span></div><p role="status">Preparing the sample response…</p>'+button('Cancel','cancel-photo','quiet'):button('Show sample response','simulate','primary')}<div class="status" role="status">${esc(state.feedback)}</div><p class="small divider">Recognising an item does not tell us whether it works or is safe.</p></section></div>`}
function identify(){
  const uncertain=['unknown','damaged'].includes(state.scenario),multiple=state.scenario==='multiple',error=state.scenario==='error',unsupported=state.scenario==='unsupported';
  if(uncertain||multiple||error||unsupported)return `<div class="story"><p class="eyebrow">Simulated photo response</p><h1>${uncertain?'I’m not sure what this is.':multiple?'Let’s choose one item.':unsupported?'Let’s choose it together.':'We could not finish that.'}</h1><p class="lead">${uncertain?'A clearer picture may help. You can choose the item yourself, too.':multiple?'Try a photo with one item clearly visible, or choose an item from the pictures.':unsupported?'This sample is outside the automatic identifier’s scope. Picture choices still work.':'Your photo is still available to replace or remove. You can also choose the item yourself.'}</p><div class="notice">${state.scenario==='damaged'?'A damaged or hidden item may be hard to recognise. Keep real damaged items with an adult.':multiple?'Multi-object detection is not connected in this prototype.':error?'This is a simulated error to demonstrate recovery.':'The result is uncertain, so no item has been confirmed.'}</div><div class="action-row">${button('Choose an item','manual-select')}${button('Back to photo','photo-open','quiet')}</div></div>`;
  return `<div class="story"><p class="eyebrow">Simulated suggestion</p><span class="result-icon" aria-hidden="true">🌀</span><h1>This looks like a fan.</h1><p class="lead">Is that right?</p><p>You make the final choice. This suggestion says nothing about the real item’s condition or safety.</p><div class="action-row">${button(state.mode==='adult'?'Yes, use a fan':'Yes, explore a fan','accept-fan','gold')}${button('Choose a different item','manual-select','quiet')}</div></div>`;
}
function confirmItem(){return `<div class="story"><div class="topline"><button class="quiet" data-action="manual-select">Change item</button><span class="chip">Item confirmed by you</span></div><span class="result-icon" aria-hidden="true">${item().icon}</span><h1>Let’s explore ${article()} ${itemNoun()}.</h1><p class="lead">${scenarioStory().title}. Open two clues, make a choice, then discover what changes it.</p><div class="notice"><strong>This is a made-up story.</strong> Its clues do not describe your real item.</div><div class="action-row">${button('Start the mission','start-mission','gold')}<a class="primary" href="lab/?item=${state.item}">Explore its parts in 3D</a>${button('Choose another item','manual-select','quiet')}</div></div>`}
function mission(){const q=scenarioStory();
 if(state.stage===0)return `<div class="story">${steps(0)}<p class="eyebrow">A made-up picture story</p><h1>${q.title}</h1>${state.item==='fan'?'<img class="story-illustration" src="assets/fan-story.webp" alt="Flo, a fictional smiling fan, in a reading corner">':`<div class="story-scene"><span class="result-icon" aria-hidden="true">${item().icon}</span><p>${q.intro}</p></div>`}${state.item==='fan'?`<p class="story-intro">${q.intro}</p>`:''}<p>Open both clues. What do they tell you?</p><div class="clues">${[q.a,q.b].map((t,i)=>`<button class="clue ${state.clues[i]?'tint':''}" data-clue="${i}" aria-expanded="${state.clues[i]}"><strong>CLUE ${i+1}${state.clues[i]?' · DISCOVERED':''}</strong><p>${state.clues[i]?t:'Tap to open this clue'}</p></button>`).join('')}</div><div class="action-row"><button class="gold" data-action="choose-answer" ${state.clues.every(Boolean)?'':'disabled'}>Choose what happens next</button>${button('Back to items','manual-select','quiet')}</div><details><summary>Word help</summary><p><strong>Reuse:</strong> use an item again. <strong>Repair:</strong> fix a fault. <strong>E-waste:</strong> electrical or electronic items people discard.</p></details></div>`;
 if(state.stage===1)return `<div class="story">${steps(1)}<p class="eyebrow">Use the clues</p><h1>${q.question}</h1><p class="lead">Choose the answer that fits what you discovered.</p><div class="answers">${q.options.map((t,i)=>`<button class="answer ${state.choice===i?'selected':''}" data-answer="${i}" aria-pressed="${state.choice===i}"><span class="letter" aria-hidden="true">${String.fromCharCode(65+i)}</span>${t}</button>`).join('')}</div><div class="status ${state.feedback?'notice':''}" role="status">${esc(state.feedback)}</div><div class="action-row">${state.correct?button('Discover why','discover','gold'):''}${button('Show a hint','hint','quiet')}${button('Read the clues again','clues-back','quiet')}</div></div>`;
 return `<div class="story">${steps(2)}<p class="eyebrow">Discover why</p><h1>${q.lesson}</h1><p class="lead">${q.why}</p><div class="panel"><p class="eyebrow">One more discovery</p><h2>${q.check}</h2><div class="answers">${q.checks.map((t,i)=>`<button class="answer" data-check="${i}"><span class="letter" aria-hidden="true">${String.fromCharCode(65+i)}</span>${t}</button>`).join('')}</div><div class="status" role="status">${esc(state.feedback)}</div></div></div>`;
}
function recap(){return `<div class="story"><div class="success-symbol" aria-hidden="true">✦</div><p class="eyebrow">Discovery complete</p><h1>You found the clue that matters.</h1><div class="panel tint"><p class="summary-label">Your ${item().name.toLowerCase()} discovery</p><h2>${scenarioStory().lesson}</h2><p>${scenarioStory().why}</p><p class="small muted">${state.progressSaved===false?'Added for this visit. Your browser could not save it.':'Saved in your Discovery Book on this browser.'}</p></div><div class="action-row">${button('Show a grown-up','handoff','gold')}${button('Explore another item','manual-select','quiet')}${button('Open Discovery Book','open-book','quiet')}</div>${state.teacher?'<div class="notice">Class discussion: tell a partner which clue changed your choice.</div>':''}</div>`}
function handoff(){return `<div class="story"><p class="eyebrow">For a grown-up</p><h1>A discovery to share.</h1><div class="panel tint"><h2>${item().name}</h2><p><strong>The child learned:</strong> ${scenarioStory().lesson}</p><p>This came from a made-up story. We have not checked the real item.</p></div><p class="lead divider">Would you like help with a real ${item().name.toLowerCase()}?</p>${item().family?button('Start the adult check','adult-handoff'):button('See the general next step','general-help')}<div class="action-row">${button('Back to Quest','back-recap','quiet')}</div></div>`}
function adult(){return `<div class="topline"><button class="quiet" data-go="home">Back to home</button><span class="chip">Household help</span></div><p class="eyebrow">1 of 3 · Your appliance</p><h1>Let’s start with your item.</h1><p class="lead">Choose a family, then your appliance. You will answer the real-item questions yourself.</p>${state.fromChild?'<div class="notice">A discovery brought you here. Only the item type carries over. Your safety answers start fresh.</div>':''}<div class="family-tabs" aria-label="Appliance families">${families.map(f=>`<button data-family="${f}" aria-pressed="${state.family===f}" class="${state.family===f?'active':''}">${f}</button>`).join('')}</div>${itemGrid('adult')}<div class="twocol"><section><label for="model">Brand and model (optional)</label><input id="model" value="${esc(state.model)}" placeholder="Only enter a label you can read safely"><p class="small muted">These details may help you check official product notices.</p></section><div class="notice"><strong>Prefer a photo?</strong><p>Try the photo helper and confirm its suggestion.</p>${button('Try photo helper','adult-photo','quiet')}</div></div><div class="action-row">${button('Continue to safety questions','safety-open')}</div>`}
const qs=['Have you already noticed smoke, fire or a burning smell?','Have you already noticed a shock, sparks or damaged wires?','Is the plug or power cord badly damaged?','Has it tripped the power or made new popping or buzzing sounds?'];
function safety(){return `<div class="story"><div class="steps"><button class="quiet" data-go="adult">1. Your appliance</button><strong>2. Safety questions</strong><span>3. Your action plan</span></div><h1>A few questions about your ${item().name.toLowerCase()}.</h1><p>Answer from what you already know. Do not switch on or open an appliance to answer.</p><form id="safety-form">${qs.map((q,i)=>`<fieldset><legend>${i+1}. ${q}</legend><div class="radio-row">${['Yes','No','Not sure'].map(v=>`<label><input type="radio" name="q${i}" value="${v}" ${state.answers[i]===v?'checked':''} required> ${v}</label>`).join('')}</div></fieldset>`).join('')}<div class="action-row"><button class="primary" type="submit">See my next step</button>${button('I cannot answer safely','unsafe','quiet')}</div></form><div class="notice small">This prototype has no live recall lookup. Exact product status remains unverified.</div></div>`}
function nextStep(){const risk=Object.values(state.answers).some(x=>x==='Yes'),unknown=Object.values(state.answers).some(x=>x==='Not sure')||Object.keys(state.answers).length<4;if(risk||unknown)return `<div class="story"><p class="eyebrow">Your next step</p><h1>${risk?'Pause and get appropriate help.':'A qualified person can help you decide.'}</h1><div class="notice warning">${risk?'You reported a warning sign. Stop using the item and keep children away. Follow the relevant official safety guidance.':'You are unsure about a warning sign. Do not test the appliance to find out.'}</div><p>If there is immediate danger, contact emergency services. This demonstration cannot diagnose the item or verify its recall status.</p><div class="action-row"><a href="https://www.productsafety.gov.au/recalls" target="_blank" rel="noopener">Official product recall search</a>${button('Review my answers','safety-open','quiet')}${button('Save this summary','save-plan','quiet')}</div><div class="status" role="status">${esc(state.feedback)}</div></div>`;return `<p class="eyebrow">Your next steps</p><h1>A plan for your ${item().name.toLowerCase()}.</h1><p class="lead">You did not report the listed warning signs. This does not confirm that the item is safe.</p><div class="twocol"><section class="panel"><h2>Find appropriate help</h2><p>Ask a qualified repairer whether an assessment is suitable and what it costs.</p><label for="suburb">Suburb or postcode (optional)</label><input id="suburb" value="${esc(state.suburb)}" placeholder="For example, Clayton"><div class="action-row">${button('View service availability','services','quiet')}</div><p class="small muted">The prototype has no live service listings.</p></section><section class="panel"><h2>Compare your own prices</h2><p class="small">Use an actual quote and a replacement price you found. Cost alone does not decide the safest or best option.</p><div class="twocol"><div><label for="quote">Repair quote (A$)</label><input id="quote" type="number" min="0" step="0.01" value="${esc(state.quote)}"></div><div><label for="replacement">Replacement price (A$)</label><input id="replacement" type="number" min="0" step="0.01" value="${esc(state.replacement)}"></div></div><div class="action-row">${button('Compare these prices','compare','quiet')}</div><div id="comparison" class="status" role="status"></div></section></div><div class="notice"><strong>Recall status: not checked.</strong> Your exact model needs verification. <a href="https://www.productsafety.gov.au/recalls" target="_blank" rel="noopener">Open official recall search</a></div><div class="action-row">${button('Save my plan','save-plan')}${button('Print summary','print','quiet')}${button('Review safety answers','safety-open','quiet')}</div><div class="status" role="status">${esc(state.feedback)}</div>`}
function services(){return `<div class="story"><p class="eyebrow">Service availability</p><h1>No live listings in this prototype.</h1><p class="lead">The planned service view will show accepted item types, contact details and when each source was checked.</p><div class="notice">Do not assume a location accepts every electrical item. Confirm directly before visiting.</div><p><a href="https://www.environment.vic.gov.au/household-waste-recycling/ewaste" target="_blank" rel="noopener">Victorian Government e-waste guidance and drop-off search</a></p><h2>What to ask a repairer</h2><ul class="short-list"><li>Do you assess this type of appliance?</li><li>Is there an inspection fee?</li><li>Will you provide a quote before doing the repair?</li></ul>${button('Back to my plan','nextstep','quiet')}</div>`}
function general(){return `<div class="story"><p class="eyebrow">Adult handoff</p><h1>Help with ${article()} ${itemNoun()}.</h1><p class="lead">Quest can teach about this item. The adult appliance assessment does not yet cover it.</p><div class="notice">A photograph cannot establish condition, repairability or safety. Check the appropriate official guidance and confirm item acceptance before visiting a service.</div><a href="https://www.environment.vic.gov.au/household-waste-recycling/ewaste" target="_blank" rel="noopener">Open Victorian e-waste guidance</a><div class="action-row">${button('Back to the discovery','back-recap','quiet')}</div></div>`}
function book(){return `<section class="discovery-invite"><div><strong>Your book has grown.</strong><p>${discoveryCount()} of 20 items explored, including your earlier picture stories.</p></div><a href="discover/#/book">Open the full Discovery Book</a></section><div class="quest-head"><div><p class="eyebrow">Your Discovery Book</p><h1>Little lessons. Lasting ideas.</h1><p class="lead">Keep the clues you discovered, one item at a time.</p></div><div class="book-mini"><strong>${state.stamps.length} / ${learningIds.length}</strong> earlier picture stories</div></div>${state.stamps.length?`<div class="item-grid">${state.stamps.map(id=>{const it=items.find(x=>x.id===id);return it?`<div class="stamp"><span class="stamp-icon" aria-hidden="true">${it.icon}</span><strong>${it.name}</strong><span>Discovery complete</span></div>`:''}).join('')}</div>`:'<div class="book-empty"><img src="assets/kids-entry.webp" alt="Friendly appliance characters waiting for a story"><div><h2>Your first discovery is waiting.</h2><p>Explore an item and use its clues. Your completed lesson will appear here.</p></div></div>'}<div class="action-row">${button('Explore an item','manual-select','gold')}</div><p class="section-note">Saved on this browser. Reset prototype clears this book on shared devices.</p>`}
function schools(){return `<div class="school-intro"><div><p class="eyebrow">For teachers</p><h1>A lesson worth talking about.</h1><p class="lead">Use pictures and a short story to help children explain an e-waste decision.</p></div><div class="lesson-duration">15–20<small>MINUTE LESSON</small></div></div><div class="twocol"><section class="panel"><p class="eyebrow">Today’s learning goal</p><h2>Which clue changes your choice?</h2><p>Children use information from a fictional story, then explain how a new clue changes the answer.</p><div class="lesson-row"><strong>1. Notice</strong><span>Identify an electrical item</span></div><div class="lesson-row"><strong>2. Explore</strong><span>Open clues in a picture story</span></div><div class="lesson-row"><strong>3. Explain</strong><span>Say why a choice fits</span></div><div class="lesson-row"><strong>4. Transfer</strong><span>Try a changed situation</span></div></section><section class="panel tint"><p class="eyebrow">Make it your lesson</p><h2>Choose an activity to explore.</h2><p>Try a short sorting round or a five-card story from the 20-item catalogue.</p><div class="action-row"><a class="primary" href="discover/">Open Sorting Station</a><a class="quiet" href="discover/#/episodes">Browse 20 discovery episodes</a></div><p class="small divider">Or revisit an original picture mission.</p><label for="lesson-item">Picture mission</label><select id="lesson-item">${items.filter(i=>learningIds.includes(i.id)).map(i=>`<option value="${i.id}">${i.name}</option>`).join('')}</select><div class="action-row">${button('Start picture mission','teacher-start','gold')}${button('Open teacher guide','teacher-print','quiet')}</div><p class="small divider">For ages 7–12. Work together, in pairs, or as a class. No student account or camera is needed.</p><p class="small muted">This is a proposed school pilot. Teacher review and curriculum mapping are still required.</p></section></div>`}
function teacherGuide(){return `<div class="story"><p class="eyebrow">Teacher discussion guide</p><h1>Which clue changed your choice?</h1><p><strong>Proposed duration:</strong> 15–20 minutes. Adapt wording to the group.</p><ol class="short-list"><li>Ask children what makes an item electrical. Use supplied pictures.</li><li>Play one mission. Let children explain their first choice.</li><li>Ask: would the answer change if nobody wanted the working item?</li><li>Show a different item. Ask which information is missing before an adult decides.</li></ol><p><strong>Observe:</strong> Can the child name a relevant clue and say why it matters?</p><p><strong>Materials:</strong> a browser, sample pictures and optional printed prompts. Keep real damaged electrical items out of the activity.</p><div class="action-row no-print">${button('Print this guide','print')}${button('Back to school mode','schools-back','quiet')}</div></div>`}
const views={home,choose,photo,identify,confirm:confirmItem,mission,recap,handoff,adult,safety,next:nextStep,services,general,book,schools,teacherGuide};
function render(){
  root.innerHTML=(views[state.view]||home)();settings();
  if(state.view==='mission'){state.resume={item:state.item,stage:state.stage,clues:[...state.clues],choice:state.choice,correct:state.correct,teacher:state.teacher};persist();}
}
function selectItem(id){
  const next=items.find(i=>i.id===id);if(!next)return false;
  if(state.item!==id){state.item=id;state.answers={};state.model='';state.quote='';state.replacement='';state.suburb='';resetMission()}
  if(next.family)state.family=next.family;return true;
}
function resetMission(){state.stage=0;state.clues=[false,false];state.choice=null;state.correct=false;state.feedback=''}
function chime(){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=660;g.gain.value=.05;o.start();g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.22);o.stop(c.currentTime+.25);o.onended=()=>c.close()}catch{}}
document.addEventListener('click',event=>{const b=event.target.closest('button,a[data-route]');if(!b)return;if(b.dataset.route){event.preventDefault();go(b.dataset.route);return}if(b.dataset.go){if(b.dataset.go==='adult'){state.mode='adult';state.fromChild=false;if(!item().family)selectItem('fan');state.family=item().family}else if(b.dataset.go==='choose'){state.mode='child';state.teacher=false;if(!learningIds.includes(state.item))selectItem('fan')}go(b.dataset.go);return}if(b.dataset.family){const first=items.find(i=>i.family===b.dataset.family);if(first){selectItem(first.id);render()}return}if(b.dataset.stage!==undefined){const stage=Number(b.dataset.stage);if(stage>=0&&stage<state.stage){state.stage=stage;go('mission')}return}if(b.dataset.item){selectItem(b.dataset.item);render();root.querySelector(`[data-item="${state.item}"]`)?.focus();say(`${item().name} selected`);return}if(b.dataset.clue!==undefined){state.clues[Number(b.dataset.clue)]=true;render();root.querySelector(`[data-clue="${b.dataset.clue}"]`)?.focus();say('Clue opened');return}if(b.dataset.answer!==undefined){state.choice=Number(b.dataset.answer);state.correct=state.choice===scenarioStory().answer;state.feedback=state.correct?'That choice fits the clues. Let’s discover why.':'Look at the clues again. You can try another choice. Hints never cost points.';render();root.querySelector(`[data-answer="${state.choice}"]`)?.focus();say(state.feedback);return}if(b.dataset.check!==undefined){if(Number(b.dataset.check)===scenarioStory().checkAnswer){state.resume=null;if(!state.stamps.includes(state.item)){state.stamps.push(state.item);chime()}state.progressSaved=persist();go('recap')}else{state.feedback='Try again. Think about what the picture can and cannot tell us.';render();say(state.feedback)}return}const action=b.dataset.action;
switch(action){case'adult-entry':state.mode='adult';state.fromChild=false;if(!item().family)selectItem('fan');state.family=item().family;go('adult');break;case'child-entry':state.mode='child';state.teacher=false;if(!learningIds.includes(state.item))selectItem('fan');go('choose');break;case'confirm-item':go('confirm');break;case'photo-open':go('photo');break;case'adult-photo':state.mode='adult';go('photo');break;case'remove-photo':state.token++;state.busy=false;if(state.photo)URL.revokeObjectURL(state.photo);state.photo='';render();say('Photo removed');break;case'simulate':{state.busy=true;state.feedback='';const token=++state.token;render();setTimeout(()=>{if(token!==state.token)return;state.busy=false;go('identify')},850);break}case'cancel-photo':state.token++;state.busy=false;render();say('Processing cancelled');break;case'manual-select':if(['book','recap','handoff','mission'].includes(state.view))state.mode='child';if(state.mode==='child'&&!learningIds.includes(state.item))selectItem('fan');go(state.mode==='adult'?'adult':'choose');break;case'accept-fan':selectItem('fan');state.answers={};go(state.mode==='adult'?'adult':'confirm');break;case'start-mission':resetMission();go('mission');break;case'choose-answer':if(state.clues.every(Boolean)){state.stage=1;go('mission')}break;case'hint':state.feedback='Ask yourself: what do the clues actually tell us, and what still needs an adult?';render();say(state.feedback);break;case'clues-back':state.stage=0;go('mission');break;case'discover':if(state.correct){state.stage=2;go('mission')}break;case'handoff':go('handoff');break;case'back-recap':go('recap');break;case'adult-handoff':state.mode='adult';state.fromChild=true;state.family=item().family;state.answers={};state.model='';state.quote='';state.replacement='';go('adult');break;case'general-help':go('general');break;case'safety-open':go('safety');break;case'unsafe':state.answers={0:'Not sure'};go('next');break;case'nextstep':go('next');break;case'services':go('services');break;case'compare':{const q=Number(state.quote),p=Number(state.replacement),out=document.getElementById('comparison');if(state.quote===''||state.replacement===''||!Number.isFinite(q)||!Number.isFinite(p)||q<0||p<=0){out.textContent='Enter a non-negative repair quote and a replacement price above zero.';return}out.textContent=`Your repair quote is A$${q.toFixed(2)}. Your replacement price is A$${p.toFixed(2)}. ${q===p?'They are equal.':`The ${q<p?'repair quote':'replacement price'} is A$${Math.abs(p-q).toFixed(2)} lower.`} Check fees and the scope of the quote.`;break}case'save-plan':state.plan={id:state.item,item:item().name,model:state.model,answers:{...state.answers},quote:state.quote,replacement:state.replacement,suburb:state.suburb,date:new Date().toISOString()};state.feedback=persist()?'Saved on this browser. Your photo is not included.':'This browser could not save the plan. You can print the summary.';render();say(state.feedback);break;case'saved-plan':if(state.plan){selectItem(state.plan.id);state.mode='adult';state.model=state.plan.model||'';state.answers={...state.plan.answers};state.quote=state.plan.quote||'';state.replacement=state.plan.replacement||'';state.suburb=state.plan.suburb||'';go('next')}break;case'open-book':go('book');break;case'print':window.print();break;case'teacher-start':state.mode='child';state.teacher=true;selectItem(document.getElementById('lesson-item').value);resetMission();go('confirm');break;case'resume-mission':{const r=state.resume;if(r&&learningIds.includes(r.item)){selectItem(r.item);state.mode='child';state.stage=[0,1,2].includes(r.stage)?r.stage:0;state.clues=Array.isArray(r.clues)&&r.clues.length===2?r.clues.map(Boolean):[false,false];state.choice=Number.isInteger(r.choice)?r.choice:null;state.correct=state.choice===scenarioStory().answer;state.teacher=r.teacher===true;if(state.stage>0&&!state.clues.every(Boolean))state.stage=0;if(state.stage===2&&!state.correct)state.stage=1;go('mission')}break;}case'teacher-print':go('teacherGuide');break;case'schools-back':go('schools');break;}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='scenario'){state.token++;state.busy=false;state.scenario=el.value;render();}if(el.id==='upload'){const f=el.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){state.feedback='Choose a JPG, PNG or WEBP image under 10 MB.';render();say(state.feedback);return}state.token++;state.busy=false;if(state.photo)URL.revokeObjectURL(state.photo);state.photo=URL.createObjectURL(f);state.feedback='Photo ready to preview. Demo results are simulated.';render();say(state.feedback)}if(/^q[0-3]$/.test(el.name))state.answers[Number(el.name.slice(1))]=el.value;});
document.addEventListener('input',event=>{if(['model','quote','replacement','suburb'].includes(event.target.id))state[event.target.id]=event.target.value});
document.addEventListener('submit',event=>{if(event.target.id==='safety-form'){event.preventDefault();if(event.target.reportValidity())go('next')}});
document.getElementById('sound').onclick=()=>{state.sound=!state.sound;if(!state.sound&&'speechSynthesis'in window)speechSynthesis.cancel();persist();settings();say(state.sound?'Sound on':'Sound off')};
document.getElementById('read').onclick=()=>{if(state.readActive&&'speechSynthesis'in window){speechSynthesis.cancel();state.readActive=false;settings();return}if(!('speechSynthesis'in window)){say('Reading aloud is unavailable. All words remain on screen.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(root.innerText);u.rate=.92;u.onend=()=>{state.readActive=false;settings()};u.onerror=()=>{state.readActive=false;settings();say('Reading aloud is unavailable. All words remain on screen.')};state.readActive=true;settings();speechSynthesis.speak(u)};
document.getElementById('clear').onclick=()=>{if(!confirm('Clear this demo’s saved progress, plan and sound preference on this browser?'))return;if(state.photo)URL.revokeObjectURL(state.photo);try{localStorage.removeItem(key);localStorage.removeItem('fixforward-discovery-v1');localStorage.removeItem('fixforward-home-v1')}catch{}if('speechSynthesis'in window)speechSynthesis.cancel();window.history.replaceState({},'','#/home');location.reload()};
window.addEventListener('beforeunload',()=>{if(state.photo)URL.revokeObjectURL(state.photo)});

// Optional browser agent tools. They call the same app state and navigation.
const modelContext=document.modelContext;
if(modelContext?.registerTool){
  const lifecycle=new AbortController();
  const register=t=>{try{Promise.resolve(modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
  register({name:'read_fixforward_state',title:'Read FixForward state',description:'Read the visible journey, confirmed item and local discovery count. Does not include photos or personal inputs.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({view:state.view,item:state.item,mode:state.mode,stage:state.view==='mission'?state.stage:null,discoveries:state.stamps.length,simulatedAI:true})});
  register({name:'start_picture_mission',title:'Start a picture mission',description:'Start a fictional learning mission for one of the eight supported learning items. Resets only the current mission and opens its Look stage. Does not complete the mission.',inputSchema:{type:'object',properties:{item:{type:'string',enum:learningIds}},required:['item'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='item')||!learningIds.includes(input.item))throw Error('Choose a supported learning item.');selectItem(input.item);state.mode='child';state.teacher=false;resetMission();go('mission');return {view:state.view,item:state.item,stage:'Look'}}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
window.addEventListener('popstate',()=>{const view=window.location.hash.replace(/^#\//,'');go(views[view]?view:'home',false)});
const firstView=window.location.hash.replace(/^#\//,'');
if(['home','choose','adult','schools','book'].includes(firstView)){state.view=firstView;state.mode=firstView==='adult'?'adult':'child'}

render();
})();
